<script setup lang="ts">
import { computed, reactive, ref } from 'vue'
import { app, start, toast } from '../session'
import { PRESETS } from '../core/presets'
import { KINDS, DEFAULTS, type GenOpts } from '../core/gen'
import { THEMES, BIOMES } from '../core/defs'
import { wordSeed } from '../core/rng'
import { SETTINGS, type Settings } from '../rules/state'
import { TONES, kinName } from '../dm/campaign'
import { PROVIDERS } from '../dm/llm'
import { mine, choose } from '../heroes'
import { sheet } from '../rules/hero'
import Bar from './Bar.vue'
import Portrait from './Portrait.vue'
import PopForm from './PopForm.vue'
import LlmForm from './LlmForm.vue'
const mode = ref<'ai' | 'dm'>(app.modalArg === 'dm' ? 'dm' : 'ai'); app.modalArg = null; const src = ref<'preset' | 'forge' | 'saved'>('preset'), preset = ref(mode.value === 'ai' ? 'crypt' : 'keep'), saved = ref(''), tone = ref('heroic'), step = ref(0), fillIt = ref(true), busy = ref(false)
const g = reactive<GenOpts>({ ...DEFAULTS, seed: wordSeed(), size: 3, levels: 2 }); const set = reactive<Settings>({ ...SETTINGS }); const P = computed(() => PRESETS.find(p => p.id === preset.value)!); const STEPS = computed(() => mode.value === 'ai' ? ['World', 'Rules', 'Storyteller', 'Your hero'] : ['World', 'Inhabitants']); void kinName
const name = ref(''); const where = computed(() => src.value === 'preset' ? P.value.name : src.value === 'saved' ? (app.saved.find(s => s.id === saved.value)?.name ?? '') : (name.value || KINDS.find(k => k.id === g.kind)!.name)); const underground = computed(() => ['dungeon', 'cave'].includes(src.value === 'preset' ? P.value.o.kind : g.kind))
const hero = computed(() => mine.list.find(h => h.id === mine.chosen) ?? null); const go = async () => { if (busy.value) return; if (src.value === 'saved' && !saved.value) { toast('Choose a world first.', true); step.value = 0; return } if (mode.value === 'ai' && !hero.value) { toast('Choose or make a hero first.', true); step.value = 3; return } if (mode.value === 'ai' && hero.value!.dead) { toast('That hero has fallen. Choose another.', true); return } busy.value = true; await start({ mode: mode.value, gen: src.value === 'preset' ? { ...P.value.o } : src.value === 'forge' ? { ...g, name: name.value || undefined } : undefined, saved: src.value === 'saved' ? saved.value : undefined, set: { ...set }, tone: tone.value, hero: hero.value?.id, populate: mode.value === 'ai' || fillIt.value }); busy.value = false }
const newHero = () => { app.modalArg = 'new'; app.screen = 'heroes' }; const llm = computed(() => PROVIDERS.find(p => p.id === app.llm.provider)!)
</script>
<template><main class="cp paper"><Bar :title="mode === 'ai' ? 'Invent a tale' : 'Build a world'" @back="app.screen = 'title'"><nav><button v-for="(s, i) in STEPS" :key="s" :class="{ on: step === i }" @click="step = i">{{ s }}</button></nav><div class="chips"><button class="chip" :class="{ on: mode === 'ai' }" @click="mode = 'ai'; step = Math.min(step, 3)">The game runs it</button><button class="chip" :class="{ on: mode === 'dm' }" @click="mode = 'dm'; step = Math.min(step, 1)">I run it</button></div></Bar>
  <div class="body scroll"><div class="in">
    <template v-if="step === 0"><div class="row wrap" style="margin-bottom:14px"><h2 class="grow">{{ mode === 'ai' ? 'Where does the story happen?' : 'What will you run?' }}</h2><div class="chips"><button class="chip s" :class="{ on: src === 'preset' }" @click="src = 'preset'">Ready-made</button><button class="chip s" :class="{ on: src === 'forge' }" @click="src = 'forge'">From a seed</button><button class="chip s" :class="{ on: src === 'saved' }" :disabled="!app.saved.length" @click="src = 'saved'">One of mine</button></div></div>
      <div v-if="src === 'preset'" class="cards"><button v-for="p in PRESETS" :key="p.id" class="wc" :class="{ on: preset === p.id }" @click="preset = p.id"><img :src="`./ui/p_${p.id}.webp`" alt="" loading="lazy"><b>{{ p.name }}</b><small>{{ p.blurb }}</small></button></div>
      <div v-else-if="src === 'saved'" class="cards"><button v-for="s in app.saved" :key="s.id" class="wc" :class="{ on: saved === s.id }" @click="saved = s.id"><img v-if="s.thumb" :src="s.thumb" alt=""><b>{{ s.name }}</b><small>A copy is made. The original stays as it is.</small></button></div>
      <div v-else class="forge"><div><span class="lab">Kind</span><div class="kinds"><button v-for="k in KINDS.filter(k => mode === 'dm' || k.id !== 'blank')" :key="k.id" :class="{ on: g.kind === k.id }" @click="g.kind = k.id"><span><b>{{ k.name }}</b><small>{{ k.blurb }}</small></span></button></div></div><div><label class="lab" for="sd">Seed</label><div class="row"><input id="sd" v-model="g.seed" class="field"><button class="btn" @click="g.seed = wordSeed()">Another</button></div><label class="lab" for="nm">Name</label><input id="nm" v-model="name" class="field" maxlength="50" placeholder="Chosen for you if left empty"><span class="lab">Size</span><div class="chips"><button v-for="(s, i) in ['Small', 'Middling', 'Large', 'Vast']" :key="s" class="chip s" :class="{ on: g.size === i + 1 }" @click="g.size = (i + 1) as any">{{ s }}</button></div><template v-if="g.kind === 'dungeon'"><label class="lab" for="lv">Floors: {{ g.levels }}</label><input id="lv" v-model.number="g.levels" type="range" min="1" max="4"></template><span class="lab">Theme{{ underground ? '' : ' of what lies below' }}</span><div class="chips"><button v-for="t in THEMES" :key="t.id" class="chip s" :class="{ on: g.theme === t.id }" @click="g.theme = t.id as any">{{ t.name }}</button></div><template v-if="!underground"><span class="lab">Land</span><div class="chips"><button v-for="(b, k) in BIOMES" :key="k" class="chip s" :class="{ on: g.biome === k }" @click="g.biome = k as any">{{ (b as any).name ?? k }}</button></div></template><template v-if="underground"><label class="lab" for="cv">Caves: {{ Math.round(g.caves * 100) }}%</label><input id="cv" v-model.number="g.caves" type="range" min="0" max="1" step=".05"></template></div></div></template>
    <template v-if="STEPS[step] === 'Rules' || STEPS[step] === 'Inhabitants'"><h2>{{ mode === 'ai' ? 'How hard, and who lives there?' : 'Who lives there?' }}</h2><button v-if="mode === 'dm'" class="opt" :class="{ on: fillIt }" style="max-width:420px" @click="fillIt = !fillIt"><span>Fill the rooms when the world is made</span><i class="tick" /></button><PopForm :set="set" :ai="mode === 'ai'" /></template>
    <template v-if="STEPS[step] === 'Storyteller'"><div class="two"><div><h2>Who tells it?</h2><p class="muted">The Storyteller is built in: it knows the rules, runs every creature, rolls in the open and never tires. It works offline and costs nothing, but it is no novelist. Connect a language model if you want free conversation. The model may only act through the same rules.</p><LlmForm /></div><div><h2>In what voice?</h2><div class="tones"><button v-for="t in TONES" :key="t.id" :class="{ on: tone === t.id }" @click="tone = t.id"><b>{{ t.name }}</b><small>{{ t.text }}</small></button></div></div></div></template>
    <template v-if="STEPS[step] === 'Your hero'"><h2>Who will you be?</h2><div class="hl"><button v-for="h in mine.list" :key="h.id" :class="{ on: mine.chosen === h.id }" :disabled="h.dead" @click="choose(h.id)"><Portrait :hero="h" :size="96" frame="bust" /><span><b>{{ h.name }}</b><small>Level {{ h.level }} {{ h.over?.race ?? sheet(h).race.name }} {{ h.over?.cls ?? sheet(h).cls.name.toLowerCase() }}<template v-if="h.dead">, fallen</template></small></span></button><button class="new" @click="newHero"><span><b>Make or bring a hero</b><small>Or fill in a sheet you already have</small></span></button></div><p v-if="hero && hero.level < set.level" class="muted">{{ hero.name }} will be raised to level {{ set.level }} for this campaign.</p></template>
  </div></div>
  <footer><div class="sum grow"><b class="cut">{{ where }}</b><span class="muted cut">{{ mode === 'ai' ? `${set.difficulty}, level ${set.level}, ${llm.name}` : fillIt ? `level ${set.level}, a boss every ${set.bossEvery || '∞'} rooms` : 'empty' }}</span></div><button v-if="step" class="btn" @click="step--">Back</button><button v-if="step < STEPS.length - 1" class="btn" @click="step++">{{ STEPS[step + 1] }}</button><button class="btn primary big" :disabled="busy" @click="go">{{ mode === 'ai' ? 'Begin' : 'Make it' }}</button></footer></main></template>
<style scoped>
.cp{position:fixed;inset:0;display:flex;flex-direction:column}nav{display:flex}nav button{padding:6px 12px;font-weight:500;color:var(--ink2);border-bottom:4px solid transparent}nav .on{color:var(--ink);border-color:var(--spot)}.body{flex:1;min-height:0}.in{max-width:1400px;padding:24px clamp(18px,3.2vw,48px) 50px;margin:0 auto}.in h2{font:800 36px/1 var(--serif)}
.cards{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,240px),1fr));gap:26px 24px}.wc{display:flex;flex-direction:column;gap:0}.wc img{width:100%;aspect-ratio:16/10;object-fit:cover;display:block;margin-bottom:9px}.wc b{font:700 23px/1 var(--serif)}.wc small{color:var(--ink2);font-size:16px;line-height:1.28;margin-top:4px}.wc.on{outline:5px solid var(--ink);outline-offset:5px}.wc:hover b{text-decoration:underline;text-decoration-thickness:2px;text-underline-offset:3px}
.forge{display:grid;grid-template-columns:1fr 1fr;gap:44px}.kinds,.tones{display:grid;border-top:2px solid var(--ink)}.kinds button,.tones button{display:block;padding:9px 11px 10px;border-bottom:1px solid var(--line2)}.kinds button:hover,.tones button:hover{background:var(--paper2)}.kinds .on,.tones .on{background:var(--ink)!important;color:var(--paper)}.kinds .on small,.tones .on small{color:#c9ced4}.kinds b,.tones b{display:block;font:700 21px/1.1 var(--serif)}.kinds small,.tones small{color:var(--ink2);font-size:15.5px}.two{display:grid;grid-template-columns:1.3fr 1fr;gap:44px}.two h2{margin-bottom:12px}
.hl{display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:18px;margin:16px 0}.hl button{display:flex;gap:16px;align-items:center;border-top:2px solid var(--ink);border-bottom:2px solid var(--ink)}.hl .on{background:var(--spot);color:var(--on-spot)}.hl .on small{color:inherit}.hl button:disabled{opacity:.45}.hl b{display:block;font:700 23px/1.05 var(--serif)}.hl small{color:var(--ink2);font-size:16px}.hl .new{padding:14px;min-height:100px}
footer{display:flex;gap:10px;align-items:center;padding:10px clamp(14px,3.2vw,48px) calc(10px + var(--safe-b));border-top:5px solid var(--ink)}.sum{display:grid}.sum b{font:700 23px/1.05 var(--serif)}.sum span{font-size:16px}
@media(max-width:760px){.forge,.two{grid-template-columns:1fr;gap:18px}nav{width:100%;overflow-x:auto;order:9}.cards{grid-template-columns:1fr 1fr;gap:18px 14px}.wc small{display:none}footer .btn:not(.primary){padding:0 10px}.sum span{display:none}}
</style>
